// Thin fetch wrapper around the FastAPI backend.
// Reads REACT_APP_BACKEND_URL (CRA convention) and attaches the JWT bearer token
// from localStorage on every request.
const BASE = process.env.REACT_APP_BACKEND_URL;
export const api_base = () => `${BASE}/api`;
export const TOKEN_KEY = "token";

// Feb-2026 · Zombie-session hotfix — the auth-token error details raised
// by ``backend/utils.get_current_user``. When the backend returns 401 with
// one of these details, the client's cached JWT is truly dead; we must
// clear the session and bounce the user to /login. Any OTHER 401 detail
// (rate-limit sentinel, custom endpoint reason, etc.) still throws a
// plain Error and does NOT touch the session — preserves current shape.
const AUTH_401_DETAILS = new Set([
  "token expired",
  "invalid token",
  "account_deleted",
  "account is deactivated",
]);

// Paths where a 401 must NEVER clear the user's JWT session:
//   • /login, /portal/login   — user is unauthenticated by design
//   • /portal/*, /public/*    — magic-link contexts using their OWN
//                                 token in a query string. A 401 there
//                                 means the MAGIC link is dead, not the
//                                 signed-in staff session.
function _isSessionSafePath(pathname) {
  if (!pathname) return false;
  return (
    pathname.startsWith("/login") ||
    pathname.startsWith("/portal") ||
    pathname.startsWith("/public") ||
    pathname.startsWith("/signup") ||
    pathname.startsWith("/forgot-password") ||
    pathname.startsWith("/reset-password")
  );
}

function _clearSessionAndRedirect() {
  try {
    localStorage.removeItem(TOKEN_KEY);
    localStorage.removeItem("user");
    localStorage.removeItem("tenant_slug");
    localStorage.removeItem("tenant_name");
  } catch { /* localStorage unavailable — best-effort */ }
  if (typeof window !== "undefined" && window.location) {
    // Preserve where the user was so a future phase can bounce them
    // back post-login. Path is captured, not full URL, to avoid
    // leaking any query-string tokens.
    const from = encodeURIComponent(
      (window.location.pathname || "/") + (window.location.search || ""),
    );
    window.location.assign(`/login?reason=expired&from=${from}`);
  }
}

// Feb-2026 · Diag-Timeout Task 2 — fire the client telemetry POST when
// the 30 s fetch abort trips. Fire-and-forget: any exception (fetch
// failure, JSON serialization, endpoint 429/killswitch) MUST be
// swallowed so the surfaced timeout Error keeps flowing unchanged.
// Uses ``navigator.sendBeacon`` when available so the request survives
// tab-navigation; falls back to a bare ``fetch(..., keepalive: true)``
// otherwise. Never uses the ``request()`` wrapper below because that
// would recurse into another 30 s timeout on the same broken pipe.
function _reportTimeoutTelemetry(payload) {
  try {
    const url = `${BASE || ""}/api/admin/client-telemetry/timeout`;
    const token = (() => {
      try {
        return localStorage.getItem(TOKEN_KEY) || "";
      } catch { return ""; }
    })();
    if (!token) return;  // anonymous timeouts skip telemetry (spec §2.3)
    const body = JSON.stringify({
      request_url: payload.request_url || "",
      request_method: payload.request_method || "GET",
      started_at: payload.started_at || "",
      ended_at: payload.ended_at || new Date().toISOString(),
      duration_ms: payload.duration_ms || 0,
      route_path: (typeof window !== "undefined" && window.location)
        ? window.location.pathname : "",
      user_agent: (typeof navigator !== "undefined")
        ? (navigator.userAgent || "").slice(0, 500) : "",
      request_id: payload.request_id || "",
      app_version: (typeof window !== "undefined"
        && window.__APP_VERSION__) || "",
    });
    // sendBeacon needs a Blob w/ Content-Type; it also strips Auth
    // headers, so we always take the fetch path when a token exists
    // so the endpoint's ``get_current_user`` dep sees the JWT.
    const tenantSlug = (() => {
      try { return localStorage.getItem("tenant_slug") || ""; }
      catch { return ""; }
    })();
    const headers = {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${token}`,
    };
    if (tenantSlug) headers["X-Tenant-Slug"] = tenantSlug;
    // ``keepalive`` lets the browser complete the send even if the
    // user navigates away right after the toast appears.
    fetch(url, { method: "POST", body, headers, keepalive: true })
      .catch(() => { /* swallow — telemetry MUST NOT surface errors */ });
  } catch { /* swallow — never break the surfaced timeout */ }
}

function authHeaders(outboundPath) {
  // Feb-2026 · Magic-link staff-header shadowing fix.
  //
  // Rule: when the outbound URL IS a portal magic-link path — i.e.
  // it starts with ``/portal/`` AND the credential is already carried
  // in the URL (either ``?token=`` in the query or ``/via-token/…``
  // in the path segment) — NO client-side session header may attach.
  //
  // Why: the customer magic-link surface at ``/e/estimate?token=<jwt>``
  // reads the token from the URL and hands it to endpoints like
  //   GET  /portal/quotes/via-token?token=<jwt>
  //   GET  /portal/tenant/branding?token=<jwt>
  //   POST /portal/quotes/via-token/<jwt>/approve
  // If a staff user (or any prior session) has a JWT sitting in
  // ``localStorage.token`` (auth.jsx::persist writes it on every
  // successful login, staff AND customer), the wrapper previously
  // attached that JWT as ``Authorization: Bearer <staff-jwt>``. On
  // the server the magic-link verify path can then latch onto the
  // Bearer header and reject the (correct) query token, producing
  // the recurring "Invalid estimate link" 401 that curl (with no
  // session) never sees. Blanket-stripping on all ``/portal/*``
  // calls would also strip the AUTHENTICATED customer portal header
  // (customer logs in with password, JWT is in localStorage.token,
  // and every ``/portal/*`` call needs that header). The narrower
  // rule below strips ONLY on magic-link-marker URLs, preserving
  // the authenticated customer-portal flow that K13 guards.
  //
  // Backend hardening follow-up (not in this dispatch): make
  // ``_verify_estimate_token`` prefer the query token over any
  // Bearer header when both are present. Tracked in
  // /app/memory/DIAG_MAGIC_LINK_401_RCA.md.
  const isPortalCall =
    typeof outboundPath === "string" && outboundPath.startsWith("/portal/");
  const isMagicLinkPortalCall = isPortalCall && (
    /[?&]token=/.test(outboundPath) || /\/via-token(\/|$|\?)/.test(outboundPath)
  );
  if (isMagicLinkPortalCall) {
    // Send only Content-Type — no Authorization, no X-Tenant-Slug.
    // The magic-link endpoint reads its credential from the URL.
    return { "Content-Type": "application/json" };
  }

  // Phase K13 · Feb-2026 — when this tab is running an admin
  // impersonation session (opened via ``window.open("/portal/home?
  // impersonation_token=…")``), prefer the per-tab sessionStorage
  // token over the admin's localStorage token so the admin's own
  // session (in another tab) is not touched.  Only applies while the
  // active route is a portal route.
  let token = "";
  try {
    const path = (typeof window !== "undefined" && window.location)
      ? window.location.pathname || "" : "";
    const portalToken = (typeof sessionStorage !== "undefined")
      ? (sessionStorage.getItem("portal_token") || "") : "";
    if (portalToken && path.startsWith("/portal")) {
      token = portalToken;
    }
  } catch { /* sessionStorage may be unavailable (SSR / test env) */ }
  if (!token) token = localStorage.getItem(TOKEN_KEY) || "";
  const tenantSlug = localStorage.getItem("tenant_slug") || "";
  const headers = { "Content-Type": "application/json" };
  if (token) headers["Authorization"] = `Bearer ${token}`;
  if (tenantSlug) headers["X-Tenant-Slug"] = tenantSlug;
  return headers;
}

async function request(path, options = {}, timeoutMs = 30000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  // Feb-2026 · Diag-Timeout Task 2 — capture the request start
  // timestamp + fetch URL/method so the ``AbortError`` catch can
  // fire client-side telemetry to the new
  // ``/admin/client-telemetry/timeout`` endpoint. Fire-and-forget:
  // failure to POST telemetry must NEVER block the surfaced error.
  const _startedAt = new Date();
  const _reqUrl = `${BASE}/api${path}`;
  const _reqMethod = (options.method || "GET").toUpperCase();
  let res;
  try {
    res = await fetch(_reqUrl, {
      ...options,
      headers: { ...authHeaders(path), ...(options.headers || {}) },
      signal: controller.signal,
    });
  } catch (e) {
    clearTimeout(timer);
    if (e?.name === "AbortError") {
      _reportTimeoutTelemetry({
        request_url: _reqUrl,
        request_method: _reqMethod,
        started_at: _startedAt.toISOString(),
        ended_at: new Date().toISOString(),
        duration_ms: Date.now() - _startedAt.getTime(),
        request_id: "",   // never got a response — no header available
      });
      throw new Error("Request timed out — check your connection and try again.");
    }
    throw new Error("Network error — check your connection and try again.");
  }
  clearTimeout(timer);
  // Preserve the server-issued request-id on the response object so
  // callers who catch a slow (but successful) or 504 response can
  // still correlate against the server slow-request log.
  try {
    if (res && res.headers && res.headers.get) {
      const rid = res.headers.get("x-request-id") || res.headers.get("X-Request-Id");
      if (rid) res.__requestId = rid;
    }
  } catch { /* headers may be locked in some polyfills */ }
  const text = await res.text();
  let data = null;
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = null;
    }
  }
  if (!res.ok) {
    let msg = data?.detail;
    if (Array.isArray(msg)) {
      msg = msg
        .map((e) => (e?.msg || "").replace(/^Value error,\s*/i, ""))
        .filter(Boolean)
        .join(" ");
    } else if (msg && typeof msg === "object") {
      // FastAPI custom-shape details like `{code, msg}` (e.g. 403 not_landscaping).
      msg = msg.msg || msg.message || msg.code || msg.error || null;
    }
    if (typeof msg !== "string" || !msg) msg = `Request failed (${res.status})`;
    // Feb-2026 · Zombie-session hotfix — global 401 interceptor.
    // Only fires when:
    //   1. Status is 401.
    //   2. Detail matches the known auth-token error set (NOT any 401).
    //   3. We're not already on an auth/portal/public page (loop guard).
    // Any other 401 (custom endpoint sentinel, portal magic-link 401,
    // etc.) falls through and throws exactly as before.
    if (res.status === 401 && typeof msg === "string") {
      const lower = msg.toLowerCase();
      const isAuthTokenFailure = AUTH_401_DETAILS.has(lower);
      const pathname =
        typeof window !== "undefined" && window.location
          ? window.location.pathname
          : "";
      if (isAuthTokenFailure && !_isSessionSafePath(pathname)) {
        _clearSessionAndRedirect();
        // Still throw so any in-flight caller sees a rejection and
        // stops rendering; the redirect will unmount them anyway.
      }
    }
    const err = new Error(msg);
    err.status = res.status;
    // Feb-2026 · Customer Delete UX overhaul — attach the parsed
    // response body so callers can surface rich failure payloads
    // (e.g. the 409 ``customer_has_unpaid_invoices`` shape carries
    // ``invoice_ids`` + ``invoice_count`` in ``data.detail``).
    // ``err.data`` mirrors axios' ``err.response?.data`` shape so
    // consumers can migrate later without churn.
    err.data = data;
    throw err;
  }
  return data;
}

export const api = {
  // K65.fix · Feb-2026 — ``get`` accepts an optional ``timeoutMs``
  // override so hot-path callers (e.g. CalendarSchedule::load) can
  // fail fast with an actionable retry banner instead of the
  // default 30 s "Request timed out" copy.
  get: (p, timeoutMs) => request(p, {}, timeoutMs),
  post: (p, body, timeoutMs) =>
    request(
      p,
      { method: "POST", body: body ? JSON.stringify(body) : undefined },
      timeoutMs
    ),
  put: (p, body) =>
    request(p, {
      method: "PUT",
      body: body ? JSON.stringify(body) : undefined,
    }),
  patch: (p, body) =>
    request(p, {
      method: "PATCH",
      body: body ? JSON.stringify(body) : undefined,
    }),
  request: (p, opts) => request(p, opts),
  // Feb-2026 · P7 hotfix — expose ``delete`` for API-verb parity with
  // ``get / post / put / patch``.  Historical callers used ``del`` (a
  // legacy alias to sidestep the ``delete`` reserved word in older JS);
  // both names now point at the same request. New call sites should
  // prefer ``.delete()``.
  delete: (p) => request(p, { method: "DELETE" }),
  del: (p) => request(p, { method: "DELETE" }),
};
